from ta_messaging.unparsed_message import is_unparsed_message


def wrap_to_parse_message_and_forward_to_verifier(func):
    """
    Performs parsing if needed and forwards to verifier
    :param func:
    :return:
    """

    def _unparsing_wrapper(*args, **kwargs):
        args_copied = list(args)
        if len(args_copied) and is_unparsed_message(args_copied[0]):
            # only args checked becuse MessageObserver passes message as arg, not kwarg
            unparsed_msg = args_copied[0]
            parsed_msg = unparsed_msg.parse()
            args_copied[0] = parsed_msg
            # if the list of args is empty it means verifier does not need message but still it has to be executed

        return func(*args_copied, **kwargs)

    for func_param in list(func.__dict__.keys()):
        _unparsing_wrapper.__setattr__(func_param, getattr(func, func_param))
    return _unparsing_wrapper


def wrap_to_perform_conditional_capturing(func, catching_condition):
    """

    :param func: original verifier func (user defined or query language one)
    :param catching_condition:
    :return:
    """
    params_per_condition_type = {'modulo': {'modulo_counter': 0,
                                            'modulo_index':
                                                int(catching_condition.attributes['mod_index'])
                                                if 'mod_index' in catching_condition.available_attributes else 1,
                                            },
                                 'on change': {}  # 'first_message' key is added dynamically by wrapper
                                 }

    def _wrapped_func_modulo(*args, **kwargs):
        params_per_condition_type['modulo']['modulo_counter'] += 1
        if params_per_condition_type['modulo']['modulo_counter'] % params_per_condition_type['modulo']['modulo_index'] == 0:
            params_per_condition_type['modulo']['modulo_counter'] = 0
            args_copied = list(args)
            if len(args_copied) and is_unparsed_message(args_copied[0]):
                # only args checked becuse MessageObserver passes message as arg, not kwarg
                unparsed_msg = args_copied[0]
                parsed_msg = unparsed_msg.parse()
                args_copied[0] = parsed_msg
            # if the list of args is empty it means verifier does not need message but still it has to be executed
            return func(*args_copied, **kwargs)
        else:
            return False

    def _wrapped_func_on_change(*args, **kwargs):
        args_copied = list(args)
        if len(args_copied) and is_unparsed_message(args_copied[0]):
            # only args checked becuse MessageObserver passes message as arg, not kwarg
            unparsed_msg = args_copied[0]
            payload = unparsed_msg.msg_payload
            if params_per_condition_type['on change'].setdefault('first_message', payload) != payload:
                parsed_msg = unparsed_msg.parse()
                args_copied[0] = parsed_msg
                return func(*args_copied, **kwargs)
            else:
                return False
        else:
            return False

    wrapper_per_condition_type = {'modulo': _wrapped_func_modulo,
                                  'on change': _wrapped_func_on_change}

    selected_wrapper = wrapper_per_condition_type[catching_condition.condition_type]

    for func_param in list(func.__dict__.keys()):
        selected_wrapper.__setattr__(func_param, getattr(func, func_param))
    return selected_wrapper
